import zlib
from bisect import bisect_right


def h(s):
    return zlib.crc32(s.encode('utf-8'))


class Ring:
    def __init__(self, nodes, vn=150):
        self.vn = vn
        self.pts = []
        self.owner = {}
        for n in nodes:
            self.add(n)

    def add(self, n):
        for i in range(self.vn):
            p = h('%s#%d' % (n, i))
            self.pts.append(p)
            self.owner[p] = n
        self.pts.sort()

    def remove(self, n):
        drop = set(h('%s#%d' % (n, i)) for i in range(self.vn))
        self.pts = [p for p in self.pts if p not in drop]
        for p in drop:
            self.owner.pop(p, None)

    def get(self, key):
        p = h(key)
        i = bisect_right(self.pts, p)
        if i == len(self.pts):
            i = 0
        return self.owner[self.pts[i]]


KEYS = ['key:%05d' % i for i in range(10000)]
r = Ring(['N0', 'N1', 'N2', 'N3'])
before = [r.get(k) for k in KEYS]
r.add('N4')
after = [r.get(k) for k in KEYS]
