import heapq


def merge_k_lists(lists):
    """lists: List[Optional[ListNode]] -> Optional[ListNode]"""
    heap = []
    for i, node in enumerate(lists):
        if node is not None:
            heap.append((node.val, i, node))
    heapq.heapify(heap)

    dummy = tail = None
    while heap:
        val, i, node = heapq.heappop(heap)
        if tail is None:
            dummy = tail = node
        else:
            tail.next = node
            tail = node
        if node.next is not None:
            heapq.heappush(heap, (node.next.val, i, node.next))
    if tail is not None:
        tail.next = None
    return dummy

