WRITE_KW = ('insert', 'update', 'delete', 'replace')


def route(req, replicas, lag_ms=0, max_lag_ms=500):
    sql = req['sql'].strip().lower()
    if req.get('in_tx'):
        return 'master', 'R1 事务内读写都走主库'
    if req.get('need_master'):
        return 'master', 'R2 会话 force_master（写后读）'
    if sql.startswith(WRITE_KW):
        return 'master', 'R3 写语句走主库'
    if not replicas:
        return 'master', 'R4 无健康从库，降级主库'
    if lag_ms > max_lag_ms:
        return 'master', 'R5 复制延迟超阈值，降级主库'
    return replicas[0], 'R6 普通读走从库'


assert route({'sql': 'SELECT 1', 'in_tx': True}, ['r0'])[0] == 'master'
assert route({'sql': 'SELECT 1', 'need_master': True}, ['r0'])[0] == 'master'
assert route({'sql': 'UPDATE t SET v=1'}, ['r0'])[0] == 'master'
assert route({'sql': 'SELECT 1'}, ['r0'])[0] == 'r0'
assert route({'sql': 'SELECT 1'}, [])[0] == 'master'
assert route({'sql': 'SELECT 1'}, ['r0'], lag_ms=900)[0] == 'master'
